// === Tab: mySketch ===
// This sketch is based upon the work of Tariq Rashad, which can be viewed here: https://www.openprocessing.org/sketch/533402#code

p5.disableFriendlyErrors = true

let ctx; //The rendering context.
let regenButton; //The DOM "button" element that users can press to regenerate the sketch after changing the initial parameters.
let aInput, bInput, cInput, dInput, scaleInput; //The DOM "input" elements that allow users to provide custom parameters, set the scale, etc.

let a = -2;
let b = -3;
let c = -1.2;
let d = 2; //the variables used to store the parameters for the attractor.

let displayScale = 112;

let x = Math.random() * displayScale;
let y = Math.random() * displayScale;
let x2, y2; //variables in which particle positions will be initiated, stored for manipulation, and updated.

let hue; //a variable to control hue.

let tEdge, lEdge, rEdge, hto, vto; //some variables used to manage the offset of our text/button/input elements.

const ITERATIONS_PER_FRAME = 10000;

function setup() {
	createCanvas(600, 800);
	ctx = createGraphics(540, 675);

	//defining the offset variables:

	tEdge = -35 + height * 1 / 10;
	lEdge = 50 + width / 20;
	rEdge = width * 19 / 20;
	hto = lEdge - 25;
	vto = tEdge + 17.5;

	background(24);
	textSize(20);
	textAlign(CENTER);
	fill(255);

	//creating the input elements...

	//a

	text("a:", hto, vto);
	aInput = createInput("" + a);
	aInput.size(60, 20);
	aInput.position(lEdge, tEdge);

	//b

	text("b:", hto + 125, vto);
	bInput = createInput("" + b);
	bInput.position(lEdge + 125, tEdge);
	bInput.size(60, 20);

	//c

	text("c:", hto + 250, vto);
	cInput = createInput("" + c);
	cInput.position(lEdge + 250, tEdge);
	cInput.size(60, 20);

	//d

	text("d:", hto + 376, vto);
	dInput = createInput("" + d);
	dInput.position(lEdge + 375, tEdge);
	dInput.size(60, 20);

	text("scale:", hto, vto - 25);
	scaleInput = createInput("" + displayScale);
	scaleInput.position(lEdge, tEdge - 25);
	scaleInput.size(60, 20);

	//creating the "regeneration" button

	regenButton = createButton("Regenerate");
	regenButton.position(rEdge / 2 - 40, tEdge - 40);
	regenButton.size(120, 20);
	regenButton.mousePressed(regen);

	//final setup of our rendering context:

	ctx.colorMode(HSL);
	ctx.background(0);
	ctx.noStroke();

}

function draw() {

	for (let i = 0; i < ITERATIONS_PER_FRAME; i++) {

		//Try commenting/uncommenting a few of these, or making up your own.

		x2 = Math.sin(a * x) - Math.sin(b * y)
		y2 = Math.sin(c * x) - Math.sin(d * y)

		// x2 = Math.sin(a * y) - Math.cos(b * x);
		// y2 = Math.sin(c * x) - Math.cos(d * y);

		//x2 = Math.sin(1/(a * y)) - Math.sin(b * x);
		//y2 = Math.cos(1/(c * x)) - Math.cos(d * y);

		//x2 = Math.sin(y / a) + Math.cos (b / x);
		//y2 = Math.cos (c / x) + Math.sin(d / y);

		//x2 = Math.sin(a / x + a * Math.sin(y)) + Math.cos (b / y - b * Math.sin(x));
		//y2 = Math.sin(c / y + c * Math.cos(x)) + Math.cos (d / x - d * Math.cos(y));

		// x2 = Math.cos(x / b * d / y) - Math.sin((a * x) / (b * y));
		// y2 = Math.sin(y / a * c / x) - Math.cos((c * y) / (d * x));

		xAv = (x2 + x) / 2;
		yAv = (y2 + y) / 2;

		ctx.fill((180 + 360 * Math.sqrt(Math.abs(Math.tan(xAv)/4 * Math.tan(yAv)/4))) % 360, 25 + 12.5 * Math.cos(xAv), 62.5 + 25 * Math.sin(yAv), 0.1);

		x = x2;
		y = y2;
		x2 *= displayScale;
		y2 *= displayScale;

		ctx.ellipse(ctx.width / 2 - x2, ctx.height / 2 - y2, 0.25);


	}

	//after carrying out all the 2000 updates, render the image on the screen:

	image(ctx, width * 1 / 20, height * 1 / 10);

}

/*
Below is the code for our "regenerate" function. 
It updates the sketch's parameters, 
randomizes the initial x and y positions,
and clears the rendering context. 
*/

function regen() {
	displayScale = Number(scaleInput.value());
	x = Math.random() * displayScale;
	y = Math.random() * displayScale;
	a = Number(aInput.value());
	b = Number(bInput.value());
	c = Number(cInput.value());
	d = Number(dInput.value());
	ctx.background(0);
}

